async function requestWebcamPermission() {
    try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });
        // Acceso concedido, puedes usar el stream para mostrar la webcam
        handleWebcamStream(stream);
    } catch (error) {
        console.error('Error al solicitar permiso de webcam:', error);
        // Manejar el caso en que el usuario deniega el permiso
    }
}

// Función para manejar el stream de la webcam
function handleWebcamStream(stream) {
    const videoElement = document.getElementById('webcamVideo');
    videoElement.srcObject = stream;
}

// Llamar a la función para solicitar permiso
requestWebcamPermission();
```

